WITH days AS (SELECT customer_id,(ordered_at AT TIME ZONE 'UTC')::DATE AS active_date FROM orders),previous AS (SELECT *,lag(active_date) OVER(PARTITION BY customer_id ORDER BY active_date) AS previous_date FROM days),marked AS (SELECT *,CASE WHEN previous_date IS NULL OR active_date-previous_date>3 THEN 1 ELSE 0 END AS starts FROM previous),islands AS (SELECT *,sum(starts) OVER(PARTITION BY customer_id ORDER BY active_date ROWS UNBOUNDED PRECEDING) AS island FROM marked) SELECT customer_id,min(active_date) AS start_date,max(active_date) AS end_date,count(*) AS active_days FROM islands GROUP BY customer_id,island ORDER BY customer_id,start_date;
